import React, { useEffect, useState } from 'react';
import axios             from 'axios';
import { useNavigate }   from 'react-router-dom';

type D = { _id:string; customerId:string; status:string };

export default function DeliveryDashboard() {
  const [ds, setDs] = useState<D[]>([]);
  const nav = useNavigate();

  useEffect(()=>{
    axios.get(`${process.env.REACT_APP_API_URL}/api/delivery`)
         .then(r=>setDs(r.data));
  },[]);

  const del = async (id:string)=>{
    if(!confirm('Delete?'))return;
    await axios.delete(`${process.env.REACT_APP_API_URL}/api/delivery/${id}`);
    setDs(ds.filter(x=>x._id!==id));
  };

  return (
    <div style={{padding:20}}>
      <h2>Dashboard</h2>
      <button onClick={()=>nav('/create')}>+New</button>
      <button onClick={()=>nav('/drivers')}>Drivers</button>
      <button onClick={()=>nav('/analytics')}>Analytics</button>
      <table style={{width:'100%',marginTop:10}}>
        <thead><tr><th>Customer</th><th>Status</th><th>Actions</th></tr></thead>
        <tbody>
          {ds.map(d=>
            <tr key={d._id}>
              <td>{d.customerId}</td><td>{d.status}</td>
              <td>
                <button onClick={()=>nav(`/track/${d._id}`)}>View</button>
                <button onClick={()=>nav(`/edit-delivery/${d._id}`)}>✏️</button>
                <button onClick={()=>del(d._id)}>🗑️</button>
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}
